function toolsPage() {
  const p = state.profile;
  const copy = text.routes.tools;
  return shell(`
    ${pageHeader("tools")}
    <section class="narrow centered">
      <p class="eyebrow">${p.code} · ${copy.suffix}</p>
      <h1>${copy.headline}</h1>
      <p class="lead-small">${enDailyBody(p)}</p>
    </section>
    <section class="tool-grid">
      ${p.tools
        .map(
          (tool) => `
            <button class="tool-card tool-card--link" data-route="tool/${toolSlug(tool.name)}">
              <span>${enToolLabel(tool)}</span>
              <h2>${enToolName(tool)}</h2>
              <p>${enToolText(tool)}</p>
              <span class="tool-card__arrow">Details →</span>
            </button>
          `
        )
        .join("")}
      <button class="tool-card tool-card--link" data-route="tcm">
        <span>TCM · Meridians · Acupuncture</span>
        <h2>View TCM Profile</h2>
        <p>Your personal TCM meridian, organ times and acupuncture recommendations for your type.</p>
        <span class="tool-card__arrow">Open →</span>
      </button>
      <button class="tool-card tool-card--link" data-route="praxistipps-heilpraktiker">
        <span>Body · Everyday Life · Naturopathy</span>
        <h2>Practical Tips from the Naturopath</h2>
        <p>Concrete, body-oriented impulses from Detlef Rathmer's naturopathic practice – complementing the Enneagram healing path.</p>
        <span class="tool-card__arrow">View →</span>
      </button>
    </section>
  `);
}

