function dynamikDerTypenPage() {
  const typeColors = ["","#7B7B52","#6B8E6B","#8B5E3C","#4A6670","#5A6E8C","#8B7355","#6B8E8C","#8B3A3A","#5A7A5A"];
  const cards = Object.entries(DYNAMIK_VIDEOS).map(([num, vid]) => {
    const n = parseInt(num);
    const col = typeColors[n] || "var(--copper)";
    return `
      <div style="background:var(--paper);border-radius:14px;overflow:hidden;box-shadow:0 1px 6px rgba(0,0,0,0.08);border-top:3px solid ${col};">
        <p style="margin:0;padding:0.7rem 1rem 0.5rem;font-size:0.88rem;font-weight:600;line-height:1.35;color:var(--ink);">These nine videos convey a vivid picture of the inner dynamics of the Enneagram types &ndash;
the thinking and feeling patterns, motivations, and blind spots of each type,
presented in 10&ndash;12 minutes each.
They are the most-watched videos on the channel.</p>
        <div style="position:relative;aspect-ratio:16/9;background:#000;">
          <iframe width="100%" height="100%" style="border:none;display:block;"
            src="https://www.youtube.com/embed/${vid}?rel=0"
            allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen loading="lazy"></iframe>
        </div>
        <p style="margin:0;padding:.5rem 1rem .7rem;font-size:.74rem;color:var(--muted);font-style:italic;">🇩🇪 German audio &ndash; enable auto-translated English subtitles via YouTube's settings (⚙).</p>
      </div>
    `;
  }).join("");

  return shell(`
    ${pageHeader("dynamik-der-typen")}
    <div class="section-content">
      <h1 style="font-size:1.6rem;line-height:1.3;margin-bottom:1rem;">The Inner Dynamics of the Enneagram Types</h1>
      <p style="font-size:1.05rem;line-height:1.7;margin-bottom:1.8rem;">
        These nine videos convey a vivid picture of the inner dynamics of the Enneagram types –
        the thinking and feeling patterns, motivations, and blind spots of each type,
        presented in 10–12 minutes each.
        They are the most-watched videos on the channel.
      </p>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:1.2rem;">
        ${cards}
      </div>
      ${bookTip("die-praxis-der-typbestimmung-taschenbuch", "The videos were created during this time as well &ndash; the book provides the written deep dive on type determination, step by step.", "Die Praxis der Typbestimmung")}
      ${relatedLinks([
        { route: "dynamik-des-bewusstseinszustandes", label: "Dynamik des Bewusstseinszustands" },
        { route: "bedeutung-27-subtypen", label: "Bedeutung der 27 Subtypes" },
        { route: "enneagramm-profiling", label: "Enneagram Profiling" },
      ])}
    </div>
  `);
}

function subtypePage(code) {
  const sp = text.subtypePage;
  const entry = subtypeEntry(code);
  if (!entry) {
    return shell(`
      ${pageHeader("knowledge")}
      <section class="narrow centered">
        <button class="ghost-link" data-route="knowledge">${sp.back}</button>
        <h1>${code.toUpperCase()}</h1>
        <p class="lead-small">No detail page has been created for this subtype yet.</p>
      </section>
    `);
  }
  const details = subtypeDetails[code.toLowerCase()] || {};
  const tc = typeColorFromCode(code);
  return shell(`
    ${pageHeader("knowledge")}
    <section class="subtype-hero" style="border-top:4px solid ${tc}">
      <button class="ghost-link" data-route="knowledge">${sp.back}</button>
      <p class="eyebrow" style="color:${tc}">${entry.code} · ${text.knowledgeCard.animalPrefix} ${entry.animal_en || entry.animal}</p>
      <h1 style="color:${tc}">${entry.title_en || entry.title}</h1>
      <p class="lead-small">${entry.coreSentence_en || entry.coreSentence}</p>
      <div style="margin-top:1.25rem; border-radius:0.5rem; overflow:hidden; border:1px solid var(--line); cursor:zoom-in;"
           data-comic-open="${code.toLowerCase()}" title="Tap to zoom in">
        <img src="${CDN}assets/comics/${code.toLowerCase()}.jpg"
             alt="Comic: ${enCode(entry.code)} &ndash; ${entry.title_en || entry.title}"
             style="width:100%; display:block; filter:contrast(1.05); pointer-events:none;" />
      </div>
      <div style="margin-top:0.6rem; padding:0.65rem 0.85rem; background:var(--surface2,rgba(0,0,0,0.04)); border-radius:0.4rem; border-left:3px solid var(--line);">
        <p style="font-size:0.78rem; color:var(--muted); line-height:1.55; margin:0;"><strong style="color:var(--ink-mid,var(--ink)); font-size:0.8rem;">${(COMIC_EN[code.toLowerCase()] || {}).title || ''}</strong><br>${(COMIC_EN[code.toLowerCase()] || {}).caption || ''}</p>
      </div>
      <button class="ghost-link" data-tier-laut="${entry.animal}"
              style="margin-top:0.75rem; font-size:0.9rem; opacity:0.85;">
        🔊 ${entry.animal_en || entry.animal} call
      </button>
    </section>
    ${(details.meinKompass_en || details.meinKompass) ? meinKompassSection(details.meinKompass_en || details.meinKompass, sp) : ""}
    ${(function(){ const dn = parseInt(code.match(/\d+/)[0]); const dv = DYNAMIK_VIDEOS[dn]; return dv ? `
    <section class="narrow" style="padding-top:0;padding-bottom:0;">
      <h3 style="margin:0 0 0.6rem;font-size:1rem;color:${tc};">The Dynamics of Type ${dn} <span style="font-size:.78rem;font-weight:400;opacity:.72;">(German · turn on CC for English subtitles)</span></h3>
      <div style="position:relative;aspect-ratio:16/9;border-radius:10px;overflow:hidden;box-shadow:0 1px 6px rgba(0,0,0,0.1);">
        <iframe width="100%" height="100%" style="border:none;display:block;"
          src="https://www.youtube.com/embed/${dv}?rel=0"
          allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen loading="lazy"></iframe>
      </div>
    </section>` : ""; })()} 
    <section class="subtype-sections">
      ${sectionBlock("verstehen", sp.rooms.verstehen, verstehenInner(entry, sp) + impulseBlock(SUBTYP_IMPULSE[code.toLowerCase()], tc, code), tc)}
      ${sectionBlock("spueren", sp.rooms.spueren, spuerenInner(entry, sp), tc)}
      ${sectionBlock("regulieren", sp.rooms.regulieren, regulierenInner(entry, sp), tc)}
      ${sectionBlock("unterstuetzen", sp.rooms.unterstuetzen, entry.heilmittel ? (hasHeilwissen() ? heilmittelSection(entry.heilmittel, oelForType(entry.code), entry.code) : heilwissenLock()) : "", tc)}
      ${sectionBlock("verkoerpern", sp.rooms.verkoerpern, verkoerpernInner(entry, sp), tc)}
      ${sectionBlock("vertiefen", sp.rooms.vertiefen, vertiefungSection(details.vertiefung, sp), tc)}
    </section>
    ${hasHeilwissen() ? tcmInlineBlock(tcmForType(entry.code)) : ""}
    ${hasHeilwissen() ? kindheitInlineBlock(kindheitForType(entry.code)) : ""}
    <section class="narrow" style="padding-top:0; padding-bottom:0;">
      ${bookTip(`einzelstudie-${code.toLowerCase()}`, `The complete individual study on ${enCode(entry.code)} &ndash; ${entry.title}. Approx. 70 pages of in-depth psychological analysis.`, `Einzelstudie ${entry.code.toUpperCase()}: ${entry.title}`)}
    </section>
    ${querverbindungen(entry)}
    <section class="narrow" style="padding:0 0 0.5rem;">
      <details class="subtype-note-wrap">
        <summary class="subtype-note-toggle">📝 My Notes on ${enCode(entry.code)}</summary>
        <textarea class="subtype-note-area" data-note-key="note-${code}" oninput="localStorage.setItem(this.dataset.noteKey,this.value)" placeholder="Personal observations, client examples, thoughts …"></textarea>
      </details>
    </section>
    ${beratungsCTA()}
  `);
}

function heilwissenLock(title = "Remedies, TCM & Kindheitsprägung") {
  return `
    <div class="heilwissen-lock">
      <span class="heilwissen-lock__icon">🔒</span>
      <div>
        <strong>${title}</strong>
        <p>This content is part of the Healing Compass upgrade.</p>
      </div>
      <button class="heilwissen-lock__btn" data-route="freischalt/heilwissen">Upgrade ansehen →</button>
    </div>
  `;
}

